****************************************************************	        FACES**** Code to modify the text buffer to produces different types* of text faces.*** Version 1.0* November 1986* By Bennet Marks** Change History** Version 2.0    May 8, 1987   Steven E. Glass**     Shadowing has	been added and the case in outlining where*     the character	does not cross a word boundary has been*     fixed.** 12 Mar 89	Steven Glass** Made this file use the TextEquates in QuickDraw project.** Found one conflict:  ImageWidth.  In Faces.Equs it was* TEMP2.  In TextEquates, it is Temp1.  Seems to be used as* local temp so I made new equate where needed: ThisImageWidth* Equ to Temp2.  Sure hope it all works.** (When we were done the file equaled the file made the old* way.)*******************************************************************************************************************************	  Copyright (C) 1986-1989*	  All Rights Reserved*	  Apple Computer, Inc.***************************************************************	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:qd.data.asm'	include '::qd:qdequates:textEquates'***************************************************	Imports	         ***************************************************	Import QDStart	Import BusyEC4***************************************************	Entries	         ***************************************************	ENTRY nStyleExtents	ENTRY nStyleText	Entry SmearDownNBurn	Entry U1D1Smear	Entry LeftRightSmear	Entry OOWShadow	Entry ShadePointers	Entry ShadeExtents	Entry OOWOutline	Entry nBText	Entry nBChar	Entry leftBitMask	Entry rightBitMask	Entry DoShadow	Entry DoOline	Entry DoItalic	Entry PostUlinePatch	Entry PreUlinePatch	Entry PRestoreTB1	Entry PGetTB2Handle	Entry PSetTB2	Entry RealGetFntInf	Entry NewStdTxBnds	Entry PRestoreFW	Entry PSaveFW	Entry PCalcFBRX	Entry StuffItInTable	Entry NewGetFontInfo	Entry OrigGFIAdr********************************************************************************************************************************************;                copy faces/VectorSetup**************************************************************** SetupTextVectors** This code saves the old vectors and puts the new ones* in place.**************************************************************** SetupTextVectors START	Export SetupTextVectorsSetupTextVectors	PROC	Redirect SetUpFontInfo	Redirect StdTxMeas	Redirect StdText	Redirect StdTxBnds	Redirect SetTB	Redirect ResetTB	Redirect StyleText	Redirect GetTextHandle	Redirect CleanUpBuffer	Redirect StyleExtents	Redirect DoUnderline	Redirect GetFntInf	lda #0	sta >OrigGFIAdr	sta >OrigGFIAdr+2	jsl GimmeVersion	and #$7F00	cmp #$0100	bne SkipThisKludge	pha	pha	PushWord #0	PushWord #$9604	_GetFuncPtr	pla	sta >OrigGFIAdr	pla	sta >OrigGFIAdr+2	lda #NewGetFontInfo-1	ldx #^NewGetFontInfo-1	jsr StuffItInTableSkipThisKludge		;	rts; These are the routines that the vectors get redirected to	JumpToNew SetUpFontInfo	JumpToNew StdTxMeas	JumpToNew StdTxBnds	JumpToNew StdText	JumpToNew SetTB	JumpToNew ResetTB	JumpToNew StyleText	JumpToNew GetTextHandle	JumpToNew CleanUpBuffer	JumpToNew StyleExtents	JumpToNew DoUnderline	JumpToNew GetFntInf	Export OrigGFIAdrOrigGFIAdr	DS.B 4;nSetUpFontInfo		;	jsl oSetUpFontInfo	jsl PCalcFBRX	rtl;nStdTxMeas		;	jsl PSaveFW	jsl oStdTxMeas	jsl PRestoreFW	rtlnStdText		;	jsl PSaveFW	jsl oStdText	jsl PRestoreFW	rtlnStdTxBnds		;	jsl PSaveFW	jsl NewStdTxBnds	jsl PRestoreFW	rtlnGetFntInf		;	jsl PSaveFW	jsl RealGetFntInf	jsl PRestoreFW	rtl;nSetTB		;	jsl oSetTB	jsl PSetTB2	rtlnResetTB		;	jsl oResetTB	jsl PSetTB2	rtl;nGetTextHandle		;	jsl oGetTextHandle	jsl PGetTB2Handle	rtl;nCleanUpBuffer		;	jsl PRestoreTB1	jsl oCleanUpBuffer	rtl;nDoUnderline		;;	jsl PreUlinePatch	bcs DontUline;	jsl oDoUnderline	jsl PostUlinePatch;DontUline		;	rtl;****  NOTE:  replacement routine for StyleText/StyleExtents****         can be	found in faces.patches - BHM  x6245  4/6/87;;**************************************************************** RestoreTextVectors** This code restores the old vectors.***************************************************************	Export RestoreTextVectorsRestoreTextVectors	Restore SetUpFontInfo	Restore StdTxMeas	Restore StdText	Restore StdTxBnds	Restore SetTB	Restore ResetTB	Restore StyleText	Restore GetTextHandle	Restore CleanUpBuffer	Restore StyleExtents	Restore DoUnderline	Restore GetFntInf	lda >OrigGFIAdr	ora >OrigGFIAdr+2	beq SkipThisKludgeToo	lda >OrigGFIAdr+2	tax	lda >OrigGFIAdr	jsr StuffItInTableSkipThisKludgeToo		;	rts	ENDP******************************************************************* StuffItInTable** This routine takes the address passed	in the a & x register* and puts it into QuickDraw's Tool Pointer Table at the* location for GetFontInfo.******************************************************************* StuffItInTable   START	Export StuffItInTableStuffItInTable	PROCGetFontInfoCallNumber equ $96	DefineStackOrigDirect	WORDTablePtr	LONGNewPointer	LONG	phx	pha	pha	pha	PushWord #0	PushWord #4	_GetTSPtr	phd	tsc	tcd	ldy #4*GetFontInfoCallNumber	lda NewPointer	sta [TablePtr],y	iny	iny	lda NewPointer+2	sta [TablePtr],y	pld	pla	pla	pla	pla	rts	ENDP********************************************************************************************************************************************;                copy faces/faces.patches;;This file, part of	QD.AUX, patches the	QDII code to fix bugs,;implement new style mods, etc. ;;A:  after SetUpFontInfo (and the current patches following	it),;execute:;;* PCalcFBRX      START	Export PCalcFBRXPCalcFBRX	PROC;	lda txFace	bit #olineBit	beq NotOline	inc extra	lda txFace;NotOline		;	bit #shadowBit	beq NotShadow	inc extra	inc extra;NotShadow		;	ldx #512	lda xFontWidth,x	;"original" fontWidth	bne ItsForced;not forced:	lda fRectMax	;(actually fbrExtent by now)	clc	adc extra	sta temp	lda txFace	and #ulineBit	beq NotUline*              inc extra	;OUT!	inc temp;NotUline		;;;	lda txFace	and #italBit	beq NotItal;italics:	lda ascent	cmp descent	bpl AscentBigger	lda descentAscentBigger		;	  ;larger of ascent, descent in acc.	lsr a	lsr a	;extra extent for italics	clc	adc temp	sta tempNotItal		;;	lda temp	clc	adc chExtra+2	adc spExtra+2	adc #2	;for possible rounding;	ldx #256	sta fontWidth,x	;new fontWidth value;ItsForced		;;in the acc. we have the "true" fontWidth - either a forced	value, or;one calculated from the current font and grafport fields	ldx #512	sta trueFBRXtnt,x	rtl	ENDP;;-----------------------------------------------------------------------------;;B1:  before any subroutine that calls SetUpFontInfo, execute;* PSaveFW        START	Export PSaveFWPSaveFW	PROC	ldx #256	lda fontWidth,x	ldx #512	sta xFontWidth,x	rtl	ENDP;;B2:  after any such subroutine, execute:;* PRestoreFW     START	Export PRestoreFWPRestoreFW	PROC	ldx #512	lda xFontWidth,x	ldx #256	sta fontWidth,x	rtl	ENDP;;affected subroutines:  StdTxMeas, StdTxBnds, StdText, and;GetFontInfo (actually, GetFontInfo should be replaced altogether);;-----------------------------------------------------------------------------;;C:  after SetTB and ResetTB, execute;* PSetTB2        START	Export PSetTB2PSetTB2	PROC	bcc NoMemErr	rtlNoMemErr		;	PushLong #0	lda textBufRowWords	asl a	;bytes;	sta temp2;	pha	lda textBufHeight	clc	adc #2	;for outlining	pha;	_Multiply;	lda 3,s	sta temp+2	lda 1,s	clc	adc temp2	;add in 3 times for	shadow	bcc NoCarry1	inc temp+2	clcNoCarry1		;	adc temp2	bcc NoCarry2	inc temp+2	clcNoCarry2		;	adc temp2	bcc NoCarry3	inc temp+2NoCarry3		;	sta temp;	ldx #512	lda TB2Handle+2,x	sta fontTemp+2	pha	lda TB2Handle,x	sta fontTemp	pha	_SetHandleSize;	bcc NoMemErr2	rtlNoMemErr2		;;	PushLong temp	ldx #512	lda tb3Handle+2,x	pha	lda tb3Handle,x	pha	_SetHandleSize	bcc NoMemErr3	rtlNoMemErr3		;;	clc	lda #0	rtl	ENDP;;-----------------------------------------------------------------------------;;;D:  before CleanUpBuffer, execute:;* PRestoreTB1    START	Export PRestoreTB1PRestoreTB1	PROC	lda txFace	bit #olineBit+shadowBit	beq NotOlNorShadow;well, it was one or the other (or both);	ldx #512	lda xRightExtent,x	sta rightExtent	lda xLeftExtent,x	sta leftExtent;	lda xBufPtr,x	sta bufPtr	lda xBufPtr+2,x	sta bufPtr+2;	lda txFace	bit #olineBit	beq NotOline;outline:	dec chHeight	dec chHeight;;	lda txFace;NotOline		;;	bit #shadowBit	beq NotShadow	;then what are we doing here?;shadow:	dec chHeight	dec ChHeight	dec ChHeight;;NotShadow		;NotOlNorShadow		;	rtl	ENDP;;E:  after GetTextHandle, execute:;* PGetTB2Handle  START	Export PGetTB2HandlePGetTB2Handle	PROC;;allocate tb2 and tb3;;first, zero them out to make later disposal easier;	ldx #512	lda #0	sta tb2Handle,x	sta tb2Handle+2,x	sta tb3Handle,x	sta tb3Handle+2,x;	pushlong #0	;for result	pushlong #15	;a token amount	lda UserID	pha	pea 0	pushlong #0	;I assume this is not used;	_NewHandle	bcc NoMemErr1;memory error:	plx	plx	;clear stack;note carry set and	error code in acc. still	rtl	;so just return;;NoMemErr1		;	ldx #512	pla	sta tb2Handle,x	pla	sta tb2Handle+2,x;;	pushlong #0	;for result	pushlong #15	;a token amount	lda UserID	pha	pea 0	pushlong #0	;I assume this is not used;	_NewHandle	bcc NoMemErr2;memory error:	plx	plx	;clear stack;note carry set and	error code in acc. still	rtl	;so just return;;NoMemErr2		;	ldx #512	pla	sta tb3Handle,x	pla	sta tb3Handle+2,x;note carry clear still	lda #0	;so clear acc.	rtl	;and just return	ENDP;;-----------------------------------------------------------------------------*****************************************************************DisposeTB2	PROC EXPORT** Dispose of the text buffer handles*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 10 Aug 88	Steven Glass** The code did not push the handle correctly before* making the dispose call.*****************************************************************;;also, tb3	ldx #512	lda tb2Handle+2,x	pha	lda tb2Handle,x	pha	_DisposeHandle	ldx #512	lda tb3Handle+2,x	pha	lda tb3Handle,x	pha	_DisposeHandle	rtl	;and just return	ENDP;;*******************************************************************************			                 **  replacement for StyleText/StyleExtents.  This version puts underlining    **  after italics, which saves us a mess	of trouble.	                 **			                 **  Bennet Marks  x6245  4/6/87		                 **			                 *******************************************************************************;;* nStyleText     START	Export nStyleTextnStyleText	PROC;;	stz justExtents	;style both text buffer and extents	bra DoStyle;	Export nStyleExtentsnStyleExtents	lda #TRUE	sta justExtents	;text buffer irrelevant;DoStyle		;	lda txFace	beq PlainStyle;	bit #boldBit	beq NotBold;it's BOLD!	jsl DoBold	lda txFaceNotBold		;;	bit #italBit	beq NotItalic;i/t/a/l/i/c/s/	jsl DoItalic	lda txFaceNotItalic		;;	bit #ulineBit	beq NotUline;underline it __________ __!	jsl DoUnderline	lda txFaceNotUline		;;	bit #olineBit+shadowBit	beq NotOlNorShadow	;nor gloom of night;;in the outline and/or shadow case, we need to keep info about the;first text buffer before switching to the others;	ldx #512	lda rightExtent	sta xRightExtent,x	lda leftExtent	sta xLeftExtent,x;	lda bufPtr	sta xBufPtr,x	lda bufPtr+2	sta xBufPtr+2,x;	lda txFace	bit #olineBit	beq NotOline;OOOUTLINEOO	jsl DoOline	lda txFace;NotOline		;;	bit #shadowBit	;although what else	could it be?	beq NotShadow;OOSHADOWOOOO	jsl DoShadow;NotShadow		;NotOlNorShadow		;            ;PlainStyle		;	rtl	ENDP******************************************		**  end of StyleText		**  (also, StyleExtents)	**		******************************************;********************************************************************************  The following patches should be executed with DoUnderline.  They fix*  an eccentricity in the underlining code that was causing	a problem with*  outlining (and would have cause a similar problem with shadowing).  To*  wit:  the underlining code was extending the underline beyond the limits*  of the text image's boundaries all the way to the nearest word boundaries,*  and relying on BlowItUp to do the necessary clipping (which it does*  admirably).  But	when outlining intervenes, the outlining code sees these*  extensions, and can't outline around the "proper" edges of the underline.**  PreUlinePatch also fixes a bug in the way underling handles "utter nulls",*  characters that have 0 image width (no image pixels) and	0 character width*  (no pen change).**  Bennet Marks  x6245  3/4/87*******************************************************************************;********************************************************************************  PreUlinePatch**  This patch determines whether any underlining should in fact be done.*  If not, it returns with the carry set; o.w. clear.  If the carry is*  set, neither the	underlining nor PostUlinePatch should be executed.**  PreUlinePatch duplicates some of the	effort found in DoUnderline.  But*  it gets it right.*******************************************************************************;* PreUlinePatch  START	Export PreUlinePatchPreUlinePatch	PROC	lda descent	cmp #2	bpl DescentOK;descent too small:	sec	rtl;DescentOK		;	lda rightExtent	cmp leftExtent	bpl ExtentsOK;extents not ok, but pens may save us:	lda bufPen	cmp startBufPen	bne PensOK;0 image width, 0 pen delta:	sec	rtl;PensOK		;ExtentsOK		;	clc	rtl	ENDP;********************************************************************************  PostUlinePatch**  This patch masks	out the troublesome	extra extents of the underline in*  the first and last words of its row.******************************************************************************** PostUlinePatch START	Export PostUlinePatchPostUlinePatch	PROC;;we have to recompute numOfBytes, because in the OnlyOneWord case the;value (0, but we need to know if we're in that case) hasn't been saved;;of course, we don't have to do any of this in the just-us-extents case 	lda justExtents	beq ClipUline	rtl	;don't bother;ClipUline		;	lda leftExtent	lsr a	lsr a	lsr a	and #first15Bits	sta temp;	lda rightExtent	lsr a	lsr a	lsr a	and #first15Bits;	sec	sbc temp	;numOfBytes value (can be 0 here)	tay;;mask out on right:	lda rightExtent	and #last4Bits	asl a	tax	lda >rightBitMask,x	and [tbRowPtr],y	;points to the underline row	sta [tbRowPtr],y;;now on left:	lda leftExtent	and #last4Bits	asl a	tax	lda >leftBitMask,x	and [tbRowPtr]	sta [tbRowPtr];	rtl	ENDP;****************************************************************** Left Bit Mask Table** Note that the "b"	directive puts its inputs into mem as* a byte stream s the byte on the left is at a lower memory* loc than the byte	on the right.****************************************************************** LeftBitMask    START	Export LeftBitMaskLeftBitMask	PROC	DC.B %11111111,%11111111	DC.B %01111111,%11111111	DC.B %00111111,%11111111	DC.B %00011111,%11111111	DC.B %00001111,%11111111	DC.B %00000111,%11111111	DC.B %00000011,%11111111	DC.B %00000001,%11111111	DC.B %00000000,%11111111	DC.B %00000000,%01111111	DC.B %00000000,%00111111	DC.B %00000000,%00011111	DC.B %00000000,%00001111	DC.B %00000000,%00000111	DC.B %00000000,%00000011	DC.B %00000000,%00000001	ENDP****************************************************************** Right Bit Mask Table** Note that the "b"	directive puts its inputs into mem as* a byte stream s the byte on the left is at a lower memory* loc than the byte	on the right.****************************************************************** RightBitMask   START	Export RightBitMaskRightBitMask	PROC		;  ; 0	DC.B %10000000,%00000000		;  ; 1	DC.B %11000000,%00000000		;  ; 2	DC.B %11100000,%00000000		;  ; 3	DC.B %11110000,%00000000		;  ; 4	DC.B %11111000,%00000000		;  ; 5	DC.B %11111100,%00000000		;  ; 6	DC.B %11111110,%00000000		;  ; 7	DC.B %11111111,%00000000		;  ; 8	DC.B %11111111,%10000000		;  ; 9	DC.B %11111111,%11000000		;  ; 10	DC.B %11111111,%11100000		;  ; 11	DC.B %11111111,%11110000		;  ; 12	DC.B %11111111,%11111000		;  ; 13	DC.B %11111111,%11111100		;  ; 14	DC.B %11111111,%11111110		;  ; 15	DC.B %11111111,%11111111	ENDP********************************************************************************************************************************************;                copy faces/newbounds;*******************************************************************************			                 **  BChar and BText had a very subtle off-by-1 error, which cropped up in the **  underline & outline and the underline & shadow cases.  These are fixed in **  the following replacements.  Also, StdTxBnds had to be changed to access  **  the new versions.		                 **			                 *******************************************************************************;****************************************	                  **  new StdTxBnds	                  **	                  ****************************************	    ;* NewStdTxBnds   START	Export NewStdTxBndsNewStdTxBnds	PROC	lda DrawVerb	; put verb in a	bne ItsAString;it's a character:	jmp nBCharItsAString		;	jmp nBText	ENDP;****************************************	                  **  new BChar	                  **	                  ****************************************	    ;* nBChar         STARTnBChar	PROC EXPORTrectPtr	equ fontTemp;widthOfChar    equ	temp;locTEnt       equ temp+2ThisImageWidth    	equ temp2;	jsl SetUpFontInfo;	ldy #O_pnLoc+O_H	lda [portRef],y	;current pen position (hor.)	sta startBufPen;	lda #maxInt	sta leftExtent	lda #-maxInt	sta rightExtent;	jsl ValidChar	tax	;temp. storage	and #lowByte	;character width	clc	adc startBufPen	;bump pen	sta bufPen;	lda [locTPtr],y	sta locTEnt	iny	iny	lda [locTPtr],y	sec	sbc locTEnt	;get image width	bne Not0Width	bra ZeroWidth	;null image;Not0Width		;	dec a	sta ThisImageWidth	txa	;get back offset/width value	xba	and #lowByte	;character offset	clc	adc kernMax	clc	adc startBufPen	sta leftExtent;	clc	adc ThisImageWidth	sta rightExtent;ZeroWidth		;;;modify extents to reflect any style mods:	jsl StyleExtents;	lda leftExtent	cmp startBufPen	bpl SBPOK	;startBufPen is leftmost;or it's not:	sta startBufPenSBPOK		;;	lda rightExtent	inc a	cmp bufPen	bmi BPOK	;bufPen is rightmost	sta bufPen	;or at least it is nowBPOK		;;;leftmost and rightmost extents now in startBufPen and bufPen -;put them in the target rectangle:;	lda startBufPen	ldy #O_H1	sta [rectPtr],y;	lda bufPen	ldy #O_H2	sta [rectPtr],y;now take care of verticals:	ldy #O_pnLoc+O_V	lda [portRef],y	;current pen position (vert.)	tax	;temp. storage	sec	sbc ascent	ldy #O_V1	sta [rectPtr],y;	txa	clc	adc descent	ldy #O_V2	sta [rectPtr],y;;	rtl	ENDP;****************************************	                  **  new BText	                  **	                  ****************************************	    ;* nBText         START	Export nBTextnBText	PROC;rectPtr	equ fontTemp;widthOfChar    equ	temp;locTEnt       equ temp+2ThisImageWidth	equ temp2;	ldy #O_pnLoc+O_H1	lda [portRef],y	sta startBufPen	sta bufPen;	lda #maxInt	sta leftExtent	lda #-maxInt	sta rightExtent;	jsl GetNextChar	bcc NotNullString	brl NullString;NotNullString		;;	jsl SetUpFontInfo;NextChar		;	jsl ValidChar	tax	;temporary storage	and #lowByte	sta widthOfChar;	lda bufPen	sta imagePen	clc	adc widthOfChar	sta bufPen	;bump position by char width;	lda [locTPtr],y	sta locTEnt	iny	iny	lda [locTPtr],y	sec	sbc locTEnt	bne Not0Width	brl ZeroWidth	;don't touch extentsNot0Width		;;	dec a	sta ThisImageWidth;	txa	;get back offset/width value	xba	and #lowByte	;offset	clc	adc kernMax	clc	adc imagePen	tax	;temp. storage	cmp leftExtent	bpl leftOK	;leftExtent is leftmost pixel	sta leftExtent	;or, it is nowleftOK		;;;new "imagePen" value still in acc.	clc	adc ThisImageWidth	cmp rightExtent	bmi RightOK	;rightExtent is rightmost pixel	sta rightExtent	;sooner or laterRightOK		;ZeroWidth		;;	jsl GetNextChar	bcc NextChar	;if there is one;;there wasn't:;adjust extents to reflect any style mods:	jsl StyleExtents;;and jump into . . .	bra MyHack	;mine, all mine! - BHM  4/14/87;;and this is another:;NullString		;	lda startBufPen	sta leftExtent	lda bufPen	dec a	sta rightExtent;MyHack		;	lda leftExtent	cmp startBufPen	bmi leftStillOK	lda startBufPen	;winner and new championleftStillOK		;	ldy #O_H1	sta [rectPtr],y;	lda rightExtent	inc a	cmp bufPen	bpl rightStillOK	lda bufPenrightStillOK		;	ldy #O_H2	sta [rectPtr],y;;now take care of verticals:	ldy #O_pnLoc+O_V	lda [portRef],y	;current pen position (vert.)	tax	;temp. storage	sec	sbc ascent;	ldy #O_V1	sta [rectPtr],y;	txa	clc	adc descent	ldy #O_V2	sta [rectPtr],y;;	rtl	ENDP*****************************************;********************************************************************************************************************************************;                copy faces/auxgfi;;This version of GetFontInfo has been broken up to make it easier;to change and/or patch out later.  It should replace the old;GetFontInfo in the	new ROM.;****************************************	                  **  Feb. 5, 1987  5:00 pm              **	                  **  Bennet Marks  x6245                **	                  ****************************************;****************************************************************** GetFontInfo** Returns some information about the font.****************************************************************** NewGetFontInfo START	Export NewGetFontInfoNewGetFontInfo	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3FIPtr	equ RTL2+3	jsr QDStart;	lda FIPtr,s	sta temp2	lda FiPtr+2,s	sta temp2+2;	jsl GetFntInf;	jmp BusyEC4;	ENDP******************************************************************* nGetFntInf** This does the right stuff for outline.******************************************************************;* RealGetFntInf  START	Export RealGetFntInfRealGetFntInf	PROC;	jsl SetUpFontInfo;(that gives us far	more than we need, but it's ok);****  ADDED 3/4/87 TO MATCH OUTLINING:****  (and shadowing, 4/20/87);	lda txFace	bit #olineBit	beq NotOline;outlined:	inc ascent	inc descent;NotOline		;	bit #shadowBit	beq NotShadow;shadowed:	inc ascent	inc descent	inc descent;****  END OF OUTLINING PATCH (and shadowing) - BHM;NotShadow		;;	lda ascent	sta [temp2];	lda descent	ldy #o_FoInDescent	sta [temp2],y;	lda widMax	clc	adc extra	ldy #o_FoInWidmax	sta [temp2],y;	lda leading	ldy #o_FoInLeading	sta [temp2],y;	rtl	ENDP;********************************************************************************************************************************************;                copy faces/italic;********************************************************************************			                  **              subroutine DoItalic		                  **			                  **	      started 2/20/87	                  **	      Bennet Marks	x6245	                  **			                  **  This subroutine italicizes the text image currently in the text buffer.    **  It leaves the italicized version in the same text buffer.                  **			                  **  For now I hard-code the initial value of italicShift (the rightward shift  **  of the top line), italicBottom (the leftward shift of the bottom line),    **  and italicDelta (the incremental shift left for each successive line) to   **  be ascent/4, descent/4, and 1/4.  (Actually, that isn't quite "hard-       **  coded" - it's more like "firm-coded").  But these values are calculated    **  and assigned early in the code, so it will be easy to modify to use other  **  values later (probably saved in the font record later).	                  **			                  **  I also make the following assumptions:  italicShift is originally positive **  (or at least non-negative), so the top line shifts rightward (if at all);  **  italicLeft is also positive, measuring a true shift to the left (same      **  caveat about non-negative); and italicDelta is also non-negative.          **			                  **  Also, to avoid complications with the algorithm and with	buffer overflow,  **  I rule out any fonts with ascent or descent > 64.  This will probably be   **  fixed up later.			                  **			                  **  italicShift, italicLeft, and italicDelta are represented	in 16-bit fixed-  **  point form, with	the binary point between the two bytes.	 So, for example, **  $0040 represents	1/4.		                  **			                  ********************************************************************************;****************************************	                  **  7/7/87  11:30 am	                  **	                  ****************************************;* DoItalic       START	Export DoItalicDoItalic	PROC;;;some 16-bit floating-point constants:fp16	equ $1000fpOneFourth	equ $0040fpOne	equ $0100;;some local 0-page usage:****  CAUTION:  THESE MUST BE IN THIS ORDER****  TO PREVENT COLLISIONS WITH TEXT BOUNDS CALLS****  BHM - 3/4/87;italicShift	equ temp+2italicDelta	equ temp2italicBottom	equ temp2+2ThisNewY	equ fontTemptextWord	equ fontTemp+2;****  END OF CAUTION;	lda #64	cmp ascent	bmi BadAscent	cmp descent	bmi BadDescent;ascent and descent	both <= 64;	lda rightExtent	cmp leftExtent	bpl ExtentOK;no pixels to modify:	rtl;BadAscent		;BadDescent		;;what do we really want to do here?	rtl;ExtentOK		;;	lda ascent	xba	lsr a	lsr a	;ascent/4 in 16-bit	fixed-point	sta italicShift;	lda descent	xba	lsr a	lsr a;	sta italicBottom	;left shift of bottom line;	lda italicShift	xba;	and #last4Bits	;shift in pixels, 16-bit integer form;(changed from "#lowByte" - we can only	shift 0-15 pixels -	BHM  x6245 7/7/87);	clc	adc rightExtent	sta rightExtent;	lda italicBottom	xba;	and #last4Bits	;shift in pixels, 16-bit integer form;(changed from "#lowByte" - we can only	shift 0-15 pixels -	BHM  x6245 7/7/87);	sta temp	lda leftExtent	sec	sbc temp	sta leftExtent;	lda justExtents	beq ItalAll	rtl;ItalAll		;;	lda #fpOneFourth	;fixed-point version of 1/4	sta italicDelta;	lda chHeight	sta rowCounter;	lda leftExtent	lsr a	lsr a	lsr a	and #first15Bits;that's the offset from the start of the;text buffer to the	first "active" word	sta temp;	clc	adc bufPtr	sta tbRowPtr	lda bufPtr+2	bcc NoCarry1	inc aNoCarry1		;	sta tbRowPtr+2;	phb	;save	pei tbRowPtr+1	plb	plb	;set for this part of text buffer;	lda rightExtent	lsr a	lsr a	lsr a	and #first15Bits	sec	sbc temp;that's the (even) number of bytes spanned;by the active part	of the text buffer	bne MoreThanAWord	brl OnlyOneWord;MoreThanAWord		;;	sta numOfBytes	;>=2, here;PosNextRow		;	lda italicShift	bmi NegShift;positive shift:	xba;	and #last4Bits	;shift in pixels, 16-bit integer form;(changed from "#lowByte" - we can only	shift 0-15 pixels -	BHM  x6245 7/7/87);	beq PosNoShift	asl a	tax	;for shift subroutines [CHECK THAT];	ldy numOfBytes	lda (tbRowPtr),y	;rightmost word	jsl VXShiftStay	sta (tbRowPtr),y;;moving left along . . . .PosNextWord		;	dey	dey	sty ThisNewY;	lda (tbRowPtr),y	sta textWord	jsl VXShiftOut	iny	iny	ora (tbRowPtr),y	sta (tbRowPtr),y;	lda textWord	jsl VXShiftStay	ldy ThisNewY	sta (tbRowPtr),y;	tya	;to set CC's for test	bne PosNextWord;line's done:PosNoShift		;	dec rowCounter	bne PosMoreRows	brl AllDone	;all done;PosMoreRows		;	jsr SetUpNextRow	bra PosNextRow;;;NegShift		;;not only is this shift negative, but, by our assumption about;italicDelta >= 0, all further shifts will also be negative;;to handle the negative shifts, we must	add 16 to them, so we;can use the shift routines, move from left to right (to prevent;interference), and	reverse the previous roles of ShiftStay	and;ShiftOut - for example, to find out what a word shifted left;3 pixels would look like, we shift it right 13 pixels and look;at what was shifted out;;our assumption that all shifts are < 16 pixels saves us from some;complications, but	will have to be loosened up later;;italicShift is in acc.	clc	adc #fp16	;now it's positive;**** added 7/7/87 to correct round-off error (negative shifts were;    being rounded to higher absolute value, positives to lower -;    we'll make them both round to lower, i.e., towards 0);	clc	adc #fpOne	sec	sbc italicDelta;**** end of fix - BHM  x6245;	sta italicShift;NegNextRow		;	lda italicShift	xba;	and #last4Bits	;shift in pixels, 16-bit integer form;(changed from "#lowByte" - we can only	shift 0-15 pixels -	BHM  x6245 7/7/87);	beq NegNoShift;	asl a	tax	;for shift routines;	lda (tbRowPtr)	;leftmost word	jsl VXShiftOut	sta (tbRowPtr);	ldy #2;NegNextWord		;	lda (tbRowPtr),y	sta textWord	jsl VXShiftOut	sta (tbRowPtr),y	lda textWord	jsl VXShiftStay	sty ThisNewY	dey	dey	ora (tbRowPtr),y	sta (tbRowPtr),y	ldy ThisNewY;	cpy numOfBytes	beq NegRowDone;row not done - set	up for next word:	iny	iny	bra NegNextWord;NegRowDone		;NegNoShift		;	dec rowCounter	beq AllDone;rows to go:	jsr SetUpNextRow	bra NegNextRow;;OnlyOneWord		;;active text buffer	only spans one word;;positive shift:OOWPosNextRow		;	lda italicShift	bmi OOWNegShift;	xba;	and #last4Bits	;shift in pixels, 16-bit integer form;(changed from "#lowByte" - we can only	shift 0-15 pixels -	BHM  x6245 7/7/87);	beq OOWPosNoShift;	asl a	tax	;for shift routines;	lda (tbRowPtr)	jsl VXShiftStay	sta (tbRowPtr);OOWPosNoShift		;	dec rowCounter	bne OOWPosMoreRows	brl AllDone;OOWPosMoreRows		;	jsr SetUpNextRow	bra OOWPosNextRow;OOWNegShift		;	clc	adc #fp16;**** added 7/7/87 to correct round-off error (negative shifts were;    being rounded to higher absolute value, positives to lower -;    we'll make them both round to lower, i.e., towards 0);	clc	adc #fpOne	sec	sbc italicDelta;**** end of fix - BHM  x6245;	sta italicShift;OOWNegNextRow		;	lda italicShift	;added 7/7/87 for consistency and;		;safety (although not really;		;necessity)	xba;	and #last4Bits	;shift in pixels, 16-bit integer form;(changed from "#lowByte" - we can only	shift 0-15 pixels -	BHM  x6245 7/7/87);	beq OOWNegNoShift;;****  BUG FIX ADDED	7/7/87 - BHM  x6245;	asl a	tax;****  END OF BUG FIX;	lda (tbRowPtr)	jsl VXShiftOut	sta (tbRowPtr);OOWNegNoShift		;	dec rowCounter	bne OOWNegMoreRows	brl AllDone;OOWNegMoreRows		;	jsr SetUpNextRow	bra OOWNegNextRow;AllDone		;	plb	rtl;**************  subroutine SetUpNextRow**  increments the pointer, resets the bank if needed,*  subtracts italicDelta from italicShift*************;SetUpNextRow		;;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry2	inc tbRowPtr+2	pei tbRowPtr+1	plb	plb;NoCarry2		;	lda italicShift	sec	sbc italicDelta	sta italicShift;	rts;*******************************  end of SetUpNextRow******************************	ENDP********************************************************************************************************************************************;                copy faces/outline;*******************************************************************************			                 **  Doline			                 **			                 **    Bennet Marks  x6245		                 **			                 **  This routine outlines the text buffer.	                 **			                 *******************************************************************************;****************************************	                  **  10:30 am  4/29/87                  **	                  ****************************************;* DoOline        START	Export DoOlineDoOline	PROC;	inc ascent	dec VBufToLoc	inc descent;	lda rightExtent	cmp leftExtent	bpl ExtentOK;0 image width:	lda bufPen	cmp startBufPen	bne NotUtterNull;utter null - no image pixels, no pen change:	brl AllDoneNotUtterNull		;;however, there's no image.  The following is a trick to;handle this little	problem.  It can be	greatly improved;upon.;	lda startBufPen	sta leftExtent	lda bufPen	dec a	sta rightExtent	bra rightExtOK;ExtentOK		;	inc rightExtent	dec leftExtent;;**********************************************************;  This next fix assures that the outlining algorithm will;  touch and therefore "overwhelm" (essentially, replace;  with outlined version) every active word it hands over;  to BlowItUp.  This saves us from having to clear TB2.;  (there was a boundary-case problem, when the image;  didn't extend as far as the pen positions into left;  words and right words);**********************************************************;	lda startBufPen	cmp leftExtent	bpl leftExtOK	sta leftExtentleftExtOK		;;	lda bufPen	dec a	cmp rightExtent	bmi rightExtOK	sta rightExtentrightExtOK		;;;****************************************;  end of that fix;****************************************;	lda justExtents	beq OlineAll	brl AllDone;OlineAll		;;;we need to know if	shadowing is on, due to an odd boundary	case	lda txFace	and #shadowBit	tay;	ldx #512;	lda leftExtent;	cpy #0	beq NotShadow1	dec aNotShadow1		;;               	lsr a	lsr a	lsr a	and #first15Bits	sta temp;	clc	adc bufPtr	sta tbRowPtr	;first row of TB1, leftmost active word	sta tb1R1Ptr,x	lda bufPtr+2	adc #0	sta tbRowPtr+2	sta tb1R1Ptr+2,x;;;deref: 	lda tb2Handle+2,x	sta temp2+2	lda tb2Handle,x	sta temp2	ldy #2	lda [temp2],y	tax	lda [temp2];	sta temp2	stx temp2+2	clc	adc temp	sta bufPtr	;top row of TB2, leftmost active word	bcc NoCarry1	inxNoCarry1		;	stx bufPtr+2;	ldx #512;	lda temp2	sta tb2Ptr,x	lda temp2+2	sta tb2Ptr+2,x;	lda bufPtr	clc	adc bufRowBytes	sta pmRowPtr	;2nd row of TB2, matching word	sta tb2R2Ptr,x	lda bufPtr+2	adc #0	sta pmRowPtr+2	sta tb2R2Ptr+2,x;	lda txFace	and #shadowBit	tay;	lda rightExtent;	cpy #0	beq NotShadow2;	inc a	inc a;NotShadow2		;	lsr a	lsr a	lsr a	and #first15Bits	sec	sbc temp	;number of "active"	bytes (forced even)	bne MoreThanAWord;	brl OnlyOneWord;MoreThanAWord		;;	sta numOfBytes	lda chHeight	sta rowCounter;NextRow		;;;rightmost word:	ldy numOfBytes;	lda [tbRowPtr],y	xba	sta temp	;clean copy	sta temp+2	;cumulatively dirty	copy;	lsr a	ora temp+2	sta temp+2;NextWord		;	lda temp	;the word to the right	asl a	ora temp+2	sta temp+2;	sty oldY	dey	dey	bmi LeftmostWord	sty newY;	lda [tbRowPtr],y	xba	sta temp2	;clean	sta temp2+2	;this one'll get dirty	bcc LeftBit0	;carry set by asl, way above;left bit of right word not 0, must be smeared into current	word;(but, on the other	hand, we don't have to consider the effect of;the current word on the right word in this case);(is that UNDERSTOOD, you'all ?!?!?);	ora #lastBit	sta temp2+2;	lsr a	ora temp2+2	sta temp2+2;	lda temp+2	;totally smeared right word	bra RWSmeared;LeftBit0		;;in this case the right word has no bit	to disturb the current word,;but the current word MAY influence the	right word	lsr a	ora temp2+2	sta temp2+2	bcc RightBit0;right bit of current word is 1, so smear it into right word	lda temp+2	ora #firstBit	sta temp+2RightBit0		;RWSmeared		;	 ;TOTALLY smeared	ldy oldY	lda temp+2	;and here it is	xba	sta [pmRowPtr],y	;so put it away (in	TB2);set up for next loop:	lda temp2+2	sta temp+2	lda temp2	sta temp;(it might make more sense to make use of the clean copy in	TB1 rather;than use temp and temp2)	ldy newY	bra NextWord;LeftmostWord		;;finish it off:	lda temp	asl a	ora temp+2	xba	sta [pmRowPtr];	dec rowCounter	beq NoMoreRows;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry3	inc tbRowPtr+2NoCarry3		;;	lda pmRowPtr	clc	adc bufRowBytes	sta pmRowPtr	bcc NoCarry4	inc pmRowPtr+2NoCarry4		;	bra NextRow;           NoMoreRows		;;;              brl AllRowsDone;           ;*;*;*;time to smear up and down, and burn;	ldx #512	lda tb1R1Ptr,x	sta tbRowPtr	;TB1 top row, leftmost active word	lda tb1R1Ptr+2,x	sta tbRowPtr+2;;currently, pmRowPtr - left over from the earlier part of the outlining -;points to the next-to-last row of TB2,	leftmost active word.  We will use;this to get a pointer to the last row,	to be used for temporary (row-long);storage, and for the smear down.;	lda pmRowPtr	clc	adc bufRowBytes	sta bRowPtr	lda pmRowPtr+2	adc #0	sta bRowPtr+2;	lda tb2R2Ptr,x	sta pmRowPtr	;TB2 second row, matching word	lda tb2R2Ptr+2,x	sta pmRowPtr+2;;(bufPtr already points to TB1 top row,	matching word);	lda chHeight	cmp #1	bne MoreThanARow	brl OnlyOneRow;MoreThanARow		;;	sta rowCounter;;top row:	ldy numOfBytes;TRNextWord		;	lda [pmRowPtr],y	sta [bufPtr],y	;smear up (special top-row case)	sta [bRowPtr],y	;temporary unsmeared storage	dey	dey	bpl TRNextWord;NextRow2		;;	lda pmRowPtr	sta bufPtr	clc	adc bufRowBytes	sta pmRowPtr	lda pmRowPtr+2	sta bufPtr+2	adc #0	sta pmRowPtr+2;tbRowPtr will be updated at the bottom	of the loop,;which will keep it	in sync (it was 1 row off - and unused -;for the top line);	ldy numOfBytes;NextWord2		;	lda [pmRowPtr],y	;current word	sta temp	;clean copy	ora [bufPtr],y	;1 line up, and half-smeared already;(by half-smeared, I mean by the word above it - left and right smears are;already completely	done, and need not be mentioned);(or maybe I should	say "three-quarters	smeared . . . .");(anyway, that's all we need for 1 line up;so burn it!)	eor [tbRowPtr],y	sta [bufPtr],y;	lda [bRowPtr],y	;clean copy of word	1 line up	ora temp	;clean copy of current word;(making a half-smeared copy of current	word)	sta [pmRowPtr],y;	lda temp	sta [bRowPtr],y	;for next time around;	dey	dey	bpl NextWord2;any more rows?	dec rowCounter	bne RowsToGo	brl AllRowsDone;RowsToGo		;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry6	inc tbRowPtr+2NoCarry6		;	bra NextRow2;;OnlyOneWord		;****  this case completely re-written 4/28/87 - BHM;	jsl OOWOutline	;isolate it for convenience ;	brl AllRowsDone;OnlyOneRow		;;but More Than A Word, and the left-right smear has been done,;and tbRowPtr (TB1,	top row), bufPtr (TB2, top row), pmRowPtr (TB2,;second row), and bRowPtr (TB2, last row) set up;	ldy numOfBytes;OORNextWord		;	lda [pmRowPtr],y	sta [bufPtr],y	sta [bRowPtr],y	eor [tbRowPtr],y	sta [pmRowPtr],y;	dey	dey	bpl OORNextWord;AllRowsDone		;	 ;such as they are;;	ldx #512	lda tb2Ptr,x	sta bufPtr	lda tb2Ptr+2,x	sta bufPtr+2;and away we go . .	. .;AllDone		;;	inc chHeight	inc chHeight;	rtl	ENDP;;;*******************************************************************************			                 **  OOWOutline			                 **			                 **    Started 4/28/87		                 **    Bennet Marks  x6245		                 **			                 **  This does the outlining in the case where the active text buffer          **  extent (including style mods) does not span a word boundary.              **			                 *******************************************************************************;****************************************	                  **  5:10 pm 4/28/87	                  **	                  ****************************************;* OOWOutline     START	Export OOWOutlineOOWOutline	PROC;;  tbRowPtr points to top line, tb1, leftmost active word;  bufPtr points to	top line, tb2, leftmost active word ;  pmRowPtr points to second line, tb1,	leftmost active word;	lda chHeight	sta rowCounter;	lda #0	sta [bufPtr]	;saves us top-line trouble later;;first, the left and right smears:;NextRow1		;	lda [tbRowPtr]	xba	sta temp	lsr a	ora temp	sta temp	asl a	ora temp	xba	sta [pmRowPtr];	dec rowCounter	beq LeftRightDone;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2NoCarry1		;;	lda pmRowPtr	clc	adc bufRowBytes	sta pmRowPtr	bcc NoCarry2	inc pmRowPtr+2NoCarry2		;;	bra NextRow1;LeftRightDone		;;;now, the up and down smear, and the burn:;;we'll work from the bottom up ;	lda chHeight	sta rowCounter;;tbRowPtr points to	the bottom row, tb1, leftmost active word;pmRowPtr points to	the penultimate row, tb2, leftmost active word  ;	lda pmRowPtr	clc	adc bufRowBytes	sta bRowPtr	;tb2, bottom row	lda pmRowPtr+2	bcc NoCarry3	inc aNoCarry3		;	sta bRowPtr+2;	lda [pmRowPtr]	sta [bRowPtr]	sta temp	;clean copy;NextRow2		;;;move pmRowPtr and bRowPtr up one row	lda pmRowPtr	sta bRowPtr	sec	sbc bufRowBytes	sta pmRowPtr	lda pmRowPtr+2	sta bRowPtr+2	bcs NoBorrow1	dec pmRowPtr+2NoBorrow1		;;	lda [pmRowPtr]	tax	;temporary storage	ora temp	;clean copy of previous row	sta [pmRowPtr]	;now smeared from below;	txa;[bRowPtr] is already smeared from below	ora [bRowPtr]	;and now from above	eor [tbRowPtr]	;and now burned	sta [bRowPtr]	;and now done;	dec rowCounter	beq AllRowsDone;	stx temp	;requisite clean copy;	lda tbRowPtr	sec	sbc bufRowBytes	sta tbRowPtr	bcs NoBorrow2	dec tbRowPtr+2NoBorrow2		;	brl NextRow2;AllRowsDone		;	rtl	ENDP********************************************************************************************************************************************;                copy faces/shadow;*******************************************************************************			                 **  code for Shadowing style mod		                 **			                 **  started 4/16/87			                 **			                 **  Bennet Marks x6245		                 **			                 *******************************************************************************;* DoShadow       START	Export DoShadowDoShadow	PROC;	jsl ShadeExtents	bcc ShadowAll	brl AllDone	;don't shadow pixels ShadowAll		;;	jsl ShadePointers	bcc MoreThanAWord;only one word:	jsl OOWShadow	bra AllPixelsDone;MoreThanAWord		;	jsl LeftRightSmear	jsl U1D1Smear	jsl SmearDownNBurn	bra AllPixelsDone;AllPixelsDone		;;	ldx #512	lda tb2Ptr,x	sta bufPtr	lda tb2Ptr+2,x	sta bufPtr+2;AllDone		;	inc chHeight	inc chHeight	inc chHeight;	rtl	ENDP;;*******************************************************************************			                 **  ShadeExtents			                 **			                 **  Applies the shadow modifiers to ascent, descent, rightExtent, and         **  leftExtent (but not chHeight, which has to wait until after the pixels    **  are shadowed).  If there is no pixel-shadowing to be done, either         **  because we are in the "just extent" case or because the pixel map         **  is utterly null (no pixels, no pen change), ShadeExtents	returns with     **  carry set; o.w. carry clear.		                 **			                 **  started 4/20/87			                 **			                 **  Bennet Marks  x6245		                 **			                 *******************************************************************************;* ShadeExtents   START	Export ShadeExtentsShadeExtents	PROC;	inc ascent	dec VBufToLoc	inc descent	inc descent;	lda rightExtent	cmp leftExtent	bpl ExtentOK;no image pixels:	lda bufPen	cmp startBufPen	bne NotUtterNull;utter null - no image, no pen displacement:	sec	rtl;NotUtterNull		;;but still no image	- will we use a trick that most certainly;can be replaced by	something more efficient	lda startBufPen	sta leftExtent	lda bufPen	dec a	sta rightExtent;ExtentOK		;	inc rightExtent	inc rightExtent	dec leftExtent;the next piece synchs the extents to the pens, which enables;us to hit every word touching a foreground OR background pixel,;so we don't ever have to clear the shadowing buffer;(trust me);	lda startBufPen	cmp leftExtent	bpl LeftExtOK	sta leftExtentleftExtOK		;;	lda bufPen	dec a	cmp rightExtent	bmi RightExtOK	sta rightExtentRightExtOK		;;	lda justExtents	beq ShadowAll	sec	rtl;ShadowAll		;	clc	rtl	ENDP;;*******************************************************************************			                 **  ShadePointers			                 **			                 **  This routine sets up all the pointer	needed for the shadowing algorithm.  **  It also calculates the width of the active text buffer.	If that width    **  is 0 (the "only one word" case) ShadePointers returns with the carry set; **  o.w. carry clear.		                 **			                 **  started 4/20/87			                 **			                 **  Bennet Marks  x6245		                 **			                 *******************************************************************************;* ShadePointers  START	Export ShadePointersShadePointers	PROC;	ldx #512;	lda leftExtent	lsr a	lsr a	lsr a	and #first15Bits	sta temp;	clc	adc bufPtr	sta tbRowPtr	sta tb1R1Ptr,x	;tb1, row 1, leftmost active word	lda bufPtr+2	bcc NoCarry1	inc aNoCarry1		;	sta tbRowPtr+2	sta tb1R1Ptr+2,x;;find the third text buffer (the shadowing buffer):;	lda tb3Handle+2,x	sta temp2+2	lda tb3Handle,x	sta temp2;	ldy #2	lda [temp2],y	sta temp+2	lda [temp2]	sta tb2Ptr,x;{the nomenclature may mislead - tb3Handle should actually be called;"tbShadeHandle", and then it would seem more natural to put the pointer;in tb2Ptr, which itself should be called "tbNextHandle".  But so what?}	clc	adc temp	sta bufPtr	;tb3, row 1, leftmost active word	lda temp+2	sta tb2Ptr+2,x	bcc NoCarry2	inc aNoCarry2		;	sta bufPtr+2;	lda bufPtr	clc	adc bufRowBytes	sta pmRowPtr	;tb3, row 2, leftmost active word	sta tb2R2Ptr,x	lda bufPtr+2	bcc NoCarry3	inc aNoCarry3		;	sta pmRowPtr+2	sta tb2R2Ptr+2,x;	lda rightExtent	lsr a	lsr a	lsr a	and #first15Bits	sec	sbc temp	sta numOfBytes	bne MoreThanAWord	sec	rtl;MoreThanAWord		;	clc	rtl	ENDP;*******************************************************************************			                 **  LeftRightSmear			                 **			                 **  Smear the current text buffer 1 pixel left and 2 pixels right, placing    **  the smeared version in tb3 (we will need the original for burning later)  **			                 **  Started 4/16/87			                 **			                 *  *  Bennet Marks x6245		                 **			                 *******************************************************************************;****************************************	                  **  4/18/87  3:30 pm	                  **	                  ****************************************;   * LeftRightSmear START	Export LeftRightSmearLeftRightSmear	PROC;	nop	;for debugging;	lda chHeight	sta rowCounter;NextRow		;	ldy numOfBytes;;rightmost word:	lda [tbRowPtr],y	xba	sta temp;	lsr a	ora temp	lsr a	ora temp	sta temp	asl a	ora temp	sta temp;temp now has the current word fully shifted, but;without the contribution of its left neighbor;	stz temp+2	rol temp+2;temp+2 has the current word's contribution to its left neighbor;NextWord		;	sty oldY	dey	dey	sty newY;	lda [tbRowPtr],y	xba	sta temp2	lsr a	ora temp2;x will be used to hold current word's contribution to its right neighbor	ldx #0	bcc Bit0Was0;;low bit of current	word is 1 (this smears into two bits into the;right neighbor, and makes the next bit	irrelevant to that word);               	ldx #first2Bits	lsr a	ora temp2	bra RSDone	;this word's right shifts done;Bit0Was0		;	lsr a	ora temp2	bcc Bit1Was0;;next-to-low bit (and not low bit) is 1:	ldx #firstBit;Bit1Was0		;RSDone		;;	sta temp2	asl a;IMPORTANT - we keep the carry from this operation for a long time;Caveat Hacker! 	ora temp2	;current word, fully shifted	ora temp+2	;merge right contribution in	sta temp2+2	;temporary storage;	txa	;left contribution for previous word	ora temp	;which is this	xba	ldy oldY	beq LeftMostWord;	sta [pmRowPtr],y;	ldy newY	beq LeftMostWord;;set up for next row:	lda temp2+2	;current word, fully shifted	sta temp	;move it here;HERE'S where we use that carry bit:	stz temp+2	rol temp+2	;hold for next word	left;	bra NextWord;LeftMostWord		;;	lda temp2+2	xba	sta [pmRowPtr];	dec RowCounter	beq LRSmearsDone	;left & right smears done - all rows;set up for next row:;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2NoCarry1		;;	lda pmRowPtr	clc	adc bufRowBytes	sta pmRowPtr	bcc NoCarry2	inc pmRowPtr+2NoCarry2		;                	bra NextRow;LRSmearsDone		;	rtl	ENDP;;*******************************************************************************			                 **  U1D1Smear			                 **			                 **  Smear the current text buffer 1 pixel up and 1 down, placing the result   **  in the same buffer ("current text buffer" is a poor phrase, but for now   **  I'll pretend I know what I mean)                                          *   *			                 **  Started 4/18/87			                 **			                 *  *  Bennet Marks x6245		                 **			                 *******************************************************************************;****************************************	                  **  4/18/87  3:30 pm	                  **	                  ****************************************;* U1D1Smear      START	Export U1D1SmearU1D1Smear	PROC;	nop	;for debugging;;pmRowPtr currently	points to the row in tb3 that matches the bottom row;of the previous text buffer (tb1 if now outlining, tb2 if outlining).;We will use this to get a pointer to the next row down, which will be;used for row-long temporary storage, and at the very last moment turn;out to have just the right contents . . . .;	lda pmRowPtr	clc	adc bufRowBytes	sta bRowPtr	;next row down	lda pmRowPtr+2	adc #0	sta bRowPtr+2;	ldx #512	lda tb2R2Ptr,x	;shadowing buffer, second row;(what did you expect, orchestra seats?)	sta pmRowPtr	lda tb2R2Ptr+2,x	sta pmRowPtr+2;	lda chHeight	sta rowCounter;;top row:	ldy numOfBytes;TRNextWord		;	lda [pmRowPtr],y	sta [bufPtr],y	sta [bRowPtr],y;	dey	dey	bpl TRNextWord;NextRow		;	dec rowCounter	beq U1D1SmearDone;other rows:;update pointers:	lda pmRowPtr	sta bufPtr	clc	adc bufRowBytes	sta pmRowPtr	lda pmRowPtr+2	sta bufPtr+2	adc #0	sta pmRowPtr+2;	ldy numOfBytes;NextWord		;	lda [pmRowPtr],y	;current word, untainted	tax	;temporary pristine	storage;we assume the word	above is already half-smeared, by the word above IT	ora [bufPtr],y	;and now by the current word as well	sta [bufPtr],y;	txa	;get current word back	ora [bRowPtr],y	;smear with word above;(a clean cop of the word above was kept in bRowPtr)	sta [pmRowPtr],y;	txa	;clean still	sta [bRowPtr],y	;hold for next word	down;	dey	dey	bpl NextWord	bra NextRow;U1D1SmearDone		;	rtl	ENDP;;*******************************************************************************			                 **  SmearDownNBurn			                 **			                 **  Smear the current text buffer down 1	pixel and burn it with the original  **  buffer.  We will	start from the bottom and work up.	                 **			                 **  Started 4/18/87			                 **			                 *  *  Bennet Marks x6245		                 **			                 *******************************************************************************;****************************************	                  **  4/18/87  5 pm	                  **	                  ****************************************;* SmearDownNBurn START	Export SmearDownNBurnSmearDownNBurn	PROC;	nop	;for debugging;	lda chHeight	sta rowCounter;	lda bRowPtr	clc	adc bufRowBytes	sta bufPtr	lda bRowPtr+2	adc #0	sta bufPtr+2;bufPtr now points to the bottom row of	the shadow, bRowPtr	to the row;above that, and pmRowPtr above that, to the row corresponding to the bottom;row of the unshadowed text image.  tbRowPtr points to the bottom row in the;unshadowed text, and will be used for the burning.;;bottom row:	ldy numOfBytes;BRNextWord		;	lda [bRowPtr],y	sta [bufPtr],y	dey	dey	bpl BRNextWord;;penultimate row (gosh, I love that word!):	ldy numOfBytes;PURNextWord		;	lda [pmRowPtr],y	ora [bRowPtr],y	sta [bRowPtr],y	dey	dey	bpl PURNextWord;;and all the little	rows that in the houses live:;NextRow		;	ldy numOfBytes;	lda pmRowPtr	sta bRowPtr	sec	sbc bufRowBytes	sta pmRowPtr	lda pmRowPtr+2	sta bRowPtr+2	sbc #0	sta pmRowPtr+2;NextWord		;	lda [pmRowPtr],y	;get word above	ora [bRowPtr],y	;smear into current	eor [tbRowPtr],y	;FLAME ON!	sta [bRowPtr],y;	dey	dey	bpl NextWord;	dec rowCounter	beq SmrDwnNBrnDone;	lda tbRowPtr	sec	sbc bufRowBytes	sta tbRowPtr	bcs NoBorrow1	dec tbRowPtr+2NoBorrow1		;;;the other pointers	are taken care of at the top of the loop;	bra NextRow;SmrDwnNBrnDone		;;	rtl	ENDP;;*******************************************************************************			                 **  OOWShadow			                 **			                 **    Started 4/29/87		                 **    Bennet Marks  x6245		                 **			                 **  This does the shadowing in the case where the active text buffer          **  extent (including style mods) does not span a word boundary.              **			                 *******************************************************************************;****************************************	                  **  6/29/87 4:00 pm	                  **	                  ****************************************;* OOWShadow      START	Export OOWShadowOOWShadow	PROC;;  tbRowPtr points to top line, tb1, leftmost active word;  bufPtr points to	top line, tb2, leftmost active word ;  pmRowPtr points to second line, tb1,	leftmost active word;	lda chHeight	sta rowCounter;	lda #0	sta [bufPtr]	;saves us top-line trouble later;;first, the left and right smears:;NextRow1		;	lda [tbRowPtr]	xba	sta temp	lsr a	ora temp	lsr a	ora temp	sta temp	asl a	ora temp	xba	sta [pmRowPtr];	dec rowCounter	beq LeftRightDone;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2NoCarry1		;;	lda pmRowPtr	clc	adc bufRowBytes	sta pmRowPtr	bcc NoCarry2	inc pmRowPtr+2NoCarry2		;;	bra NextRow1;LeftRightDone		;;;now, up and down smear, 1 pixel each;;we'll work from the bottom up ;	lda chHeight	sta rowCounter;;tbRowPtr points to	the bottom row, tb1, leftmost active word;pmRowPtr points to	the corresponding row in the shadow buffer;	lda pmRowPtr	clc	adc bufRowBytes	sta bRowPtr	;tb2, penultimate row	lda pmRowPtr+2	bcc NoCarry3	inc aNoCarry3		;	sta bRowPtr+2;	lda [pmRowPtr]	sta [bRowPtr]	sta temp	;clean copy;NextRow2		;;;move pmRowPtr and bRowPtr up one row	lda pmRowPtr	sta bRowPtr	sec	sbc bufRowBytes	sta pmRowPtr	lda pmRowPtr+2	sta bRowPtr+2	bcs NoBorrow1	dec pmRowPtr+2NoBorrow1		;;	lda [pmRowPtr]	tax	;temporary storage	ora temp	;clean copy of previous row	sta [pmRowPtr]	;now smeared from below;	txa;[bRowPtr] is already smeared from below	ora [bRowPtr]	;and now from above	sta [bRowPtr]	;and now done;	dec rowCounter	beq Up1Dn1Done;	stx temp	;requisite clean copy;	brl NextRow2;Up1Dn1Done		;;;now smear down once more, and burn;	ldx #512	lda tb1R1Ptr,x	sta tbRowPtr	lda tb1R1Ptr+2,x	sta tbRowPtr+2;	lda chHeight	sta rowCounter;	stz temp;NextRow3		;;	lda [bRowPtr]	tax	;temporary storage,	clean copy	ora temp	;clean copy from above	eor [tbRowPtr]	;burn	sta [bRowPtr];	stx temp;	dec rowCounter	beq TwoRowsToGo;more rows:;	lda bRowPtr	clc	adc bufRowBytes	sta bRowPtr	bcc NoCarry4	inc bRowPtr+2NoCarry4		;;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry5	inc tbRowPtr+2NoCarry5		;;	bra NextRow3;;***************************************************  The rest of this	routine was re-written 6/29/87*  to fix a bug involved with shadowing	down near*  the descent line	- BHM  x6245**************************************************;;TwoRowsToGo		;;;	lda bRowPtr	clc	adc bufRowBytes	sta bRowPtr	bcc NoCarry6	inc bRowPtr+2NoCarry6		;;	lda [bRowPtr]	tax	ora temp	sta [bRowPtr];	lda bRowPtr	clc	adc bufRowBytes	sta bRowPtr	bcc NoCarry7	inc bRowPtr+2NoCarry7		;;	txa	sta [bRowPtr];               	rtl	ENDP	END